function useBusinessContext({ businessHook, initialState, flowHook }) {
  const businessContext = useMemo(() => {
    const info = businessHook.businessInfo;
    if (!info && !initialState?.businessInfo && !initialState?.projectDescription) {
      return null;
    }
    const source = info || initialState?.businessInfo;
    return {
      businessName: flowHook.projectName || source?.businessType || initialState?.projectName || void 0,
      description: source?.description || initialState?.projectDescription || void 0,
      targetAudience: source?.targetAudience || void 0,
      goals: source?.businessGoals || void 0,
      industry: source?.industry || void 0,
      uvp: source?.uvp || void 0
    };
  }, [businessHook.businessInfo, initialState, flowHook.projectName]);
  const isInternalFlow = useMemo(() => {
    return Boolean(businessContext?.description && businessContext.description.length > 10);
  }, [businessContext]);
  return { businessContext, isInternalFlow };
}

